/* reverb_recall.c — per-patch global REVERB recall (see reverb_recall.h).
 *
 * Method (binary-only, no fabrication): a Unicorn harness BUILDs the real CJu60Sim
 * effect engine (operator new 0xA83010 + CWaveGen::build @0x3C68D0) so every reverb
 * param-smoother is bound to its engine coefficient, then drives the plugin's OWN
 * value-tree dispatch (sub_...019A30 @RVA 0x3B9A30) on the real master processor and
 * hooks the effect param-smoother SETTER (sub_...022E80 @RVA 0x3C2E80) to read the
 * authoritative recall TARGET (xmm1 = smoother[+0x14], the value each coeff converges
 * to). No running-plugin captures. See scratchpad/oracle/reverb_validation_findings.md.
 *
 * The master's global output stage always runs the reverb tank (independent of the two
 * insert-effect slots), so no mode routing is needed — the per-patch coefficients below
 * override the (prepare-seeded TYPE2/TIME128) baseline reverb character.
 *
 * Three recalled quantities (value-tree indices in parentheses):
 *   REVERB LEVEL (idx 795) = front-panel blob 51  -> 10759408 (send/wet). SR- and
 *       TYPE-independent; REVLVL_LUT below is bit-exact 256/256 (kept verbatim).
 *   REVERB TYPE  (idx 876) = record byte 658 (0..5) -> the 4 DPF cutoffs (Fc, all four
 *       equal) 10759648/696/744/792, the type-5-only stage 10759488, and (jointly with
 *       TIME) the 8 Hp/Lp decay coeffs.
 *   REVERB TIME  (idx 877) = record byte 666 -> the 8 Hp/Lp coeffs (4 distinct curves,
 *       each mirrored to a second offset), as a JOINT function of (TYPE, TIME).
 *
 * The Hp/Lp coeffs are a joint (TYPE,TIME) table: the prior single-curve REVTIME_LUT
 * was the TYPE-0 slice of ONE of the eight offsets (a mis-capture) — wrong for every
 * real patch, incl. the default (TYPE2/TIME128). All four curve families + the Fc/488
 * type table here are SAMPLE-RATE independent (identical 44.1/48/96 kHz) and the
 * (TYPE,TIME) handlers are order-independent (each recomputes all DPF coeffs).
 * Data source: scratchpad/oracle/rev/type_time_full.json (CRC32 0x821bec3d over the
 * four Hp/Lp tables + Fc + R488). Cross-check: the captured TYPE2/TIME128 values equal
 * juno_prepare.c's independently-derived tank constants (two paths agree).
 *
 *   REVERB LEVEL = front-panel blob 51 (record byte 118, nibble pair)
 *   REVERB TYPE  = record byte 658 (0..5)
 *   REVERB TIME  = record byte 666 (NAME3 int8x4 low byte)
 */
#include "juno_engine.h"
#include "reverb_recall.h"
#include <string.h>

