/* TYPE 0..5 -> the 4 DPF cutoffs (Fc, all four equal) and the type-5-only stage 488. */
static const uint32_t REV_FC[6]   = {0x3d8596c4, 0x3e0566f8, 0x3e0566f8, 0x3d090dbb, 0x3f34be76, 0x3e0566f8};
static const uint32_t REV_R488[6] = {0x00000000, 0x00000000, 0x00000000, 0x00000000, 0x00000000, 0x3e500000};

static int rec_byte(const unsigned char *rec, int off)
{
    return ((rec[off] & 0xF) << 4) | (rec[off + 1] & 0xF);
}
static int blob_val(const unsigned char *rec, int bp)
{
    const unsigned char *b = rec + 16;
    return ((b[2 * bp] & 0xF) << 4) | (b[2 * bp + 1] & 0xF);
}

static void put_bits(unsigned char *state, int off, uint32_t bits)
{
    float f; memcpy(&f, &bits, 4); JF(state, off) = f;
}

void juno_apply_reverb(unsigned char *state, const unsigned char *rec)
{
    int level = blob_val(rec, 51);                 /* REVERB LEVEL (blob 51)      */
    int type  = rec_byte(rec, 658);                /* REVERB TYPE  (record 658)   */
    int time  = rec_byte(rec, 666) & 0xFF;         /* REVERB TIME  (record 666)   */
    if (type < 0) type = 0; else if (type > 5) type = 5;   /* defensive 0..5 clamp */

    /* LEVEL (idx 795) */
    put_bits(state, 10759408, REVLVL_LUT[level & 0xFF]);

    /* TYPE-only coeffs (idx 876): 4 DPF cutoffs (all equal) + type-5 stage */
    put_bits(state, 10759648, REV_FC[type]);
    put_bits(state, 10759696, REV_FC[type]);
    put_bits(state, 10759744, REV_FC[type]);
    put_bits(state, 10759792, REV_FC[type]);
    put_bits(state, 10759488, REV_R488[type]);

    /* Joint (TYPE,TIME) Hp/Lp decay coeffs (idx 876/877), each mirrored: */
    put_bits(state, 10759664, HP01[type][time]);   put_bits(state, 10759712, HP01[type][time]);
    put_bits(state, 10759680, LP01[type][time]);   put_bits(state, 10759728, LP01[type][time]);
    put_bits(state, 10759760, HP23[type][time]);   put_bits(state, 10759808, HP23[type][time]);
    put_bits(state, 10759776, LP23[type][time]);   put_bits(state, 10759824, LP23[type][time]);
}
